from google.cloud import speech_v1 as speech
from google.cloud.speech_v1 import enums

def stream_audio_chunks(audio_generator):
    client = speech.SpeechClient()
    config = {
        'encoding': enums.RecognitionConfig.AudioEncoding.LINEAR16,
        'sample_rate_hertz': 16000,
        'language_code': 'en-US',
    }
    streaming_config = {
        'config': config,
    }
    requests = (speech.StreamingRecognizeRequest(audio_content=content)
                for content in audio_generator)
    responses = client.streaming_recognize(streaming_config, requests)
    for response in responses:
        yield response

from google.cloud import speech_v1 as speech

def handle_streaming_results(responses):
    for response in responses:
        for result in response.results:
            if not result.is_final:
                print(f'Interim: {result.alternatives[0].transcript}')
            else:
                print(f'Final: {result.alternatives[0].transcript}')

from google.cloud import speech_v1 as speech
from google.cloud.speech_v1 import enums

def create_speech_client():
    return speech.SpeechClient()

def create_streaming_config(language_code='en-US', enable_automatic_punctuation=True):
    return {
        'encoding': enums.RecognitionConfig.AudioEncoding.LINEAR16,
        'sample_rate_hertz': 16000,
        'language_code': language_code,
        'enable_automatic_punctuation': enable_automatic_punctuation,
    }

from google.cloud.speech_v1 import enums

def normalize_response(response):
    return {
        'transcript': response.results[0].alternatives[0].transcript,
        'is_final': response.results[0].is_final,
    }
